 const [cart,setCart]=useState<(SaleInput&{id:string})[]>([]),[discount,setDiscount]=useState(0),[rewardsPhone,setRewardsPhone]=useState(''),[redeemReward,setRedeemReward]=useState(false),[profileOpen,setProfileOpen]=useState(false),[pickupName,setPickupName]=useState(''),[scan,setScan]=useState(''),[lastSale,setLastSale]=useState<PosReceipt|null>(null),[camera,setCamera]=useState(false),[type,setType]=useState('All'),[query,setQuery]=useState(''),[editing,setEditing]=useState<string|null>(null),[draft,setDraft]=useState<Record<string,number>>({}),[draftSauce,setDraftSauce]=useState<string|undefined>(),[checkoutBusy,setCheckoutBusy]=useState(false),[checkoutUncertain,setCheckoutUncertain]=useState(false);
 const checkoutLock=useRef(false);
